from pathlib import Path
from html import escape
p=Path(__file__).parent
nav=[('Home','/'),('Products','/products.html'),('About Us','/about.html'),('Contact','/contact.html'),('RCS SMS','/#rcs-sms'),('Privacy','/privacy-policy.html'),('Terms','/terms-and-conditions.html')]
head='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><link rel="stylesheet" href="/style.css">'''
header='<header><div class="wrap"><a href="/" style="text-decoration:none"><strong>GURUKRIPA ENTERPRISES</strong></a><nav>'+''.join(f'<a href="{url}">{name}</a>' for name,url in nav)+'</nav></div></header>'
footer='<footer><div class="wrap"><strong>GURUKRIPA ENTERPRISES</strong><p>R 1671, Matruchhaya Row House, Rajya Karmchari Vasahat, Satpur, Maharashtra 422012 · +91 86980 04560</p>'+''.join(f'<a href="{url}">{name}</a>' for name,url in nav)+'<a href="/sms-preferences.html">Opt-out</a></div></footer>'
def page(name,body):return head+f'<title>{escape(name)} | Gurukripa Enterprises</title></head><body>'+header+body+footer+'</body></html>'
def section(body,cls=''):return f'<section class="section {cls}"><div class="wrap">{body}</div></section>'
