cards='<div class="grid">'+''.join(f'<div class="card"><h3>{n}</h3><p>Business stationery and office supplies.</p><a href="https://wa.me/918698004560?text={quote("Enquiry for "+n)}">Enquire ↗</a></div>' for n in products)+'</div>'
rcs='''<section id="rcs-sms" class="section band" style="scroll-margin-top:90px"><div class="wrap"><h2>RCS SMS Campaign Dashboard</h2><p>Preview branded business messages directly on this website.</p><div class="notice"><b>Demo only:</b> No SMS sending, provider API or contact storage is active.</div><div class="stats"><div class="card"><b>0</b>Messages Sent</div><div class="card"><b>0</b>Active Campaigns</div><div class="card"><b>0</b>Contacts Stored</div></div><div class="twocol"><div class="panel"><h3>Campaign Builder</h3><label>Campaign Name</label><input value="Gurukripa Product Promotion"><label>Estimated Recipient Volume</label><select><option>1,000</option><option>2,000</option><option>3,000</option><option>5,000</option></select><label>Message Content</label><textarea id="rcsMessage" rows="5">Explore stationery and business books from Gurukripa Enterprises.</textarea><label>CTA Text</label><input id="rcsCta" value="Enquire on WhatsApp"><p><button class="btn" id="updatePreview">Update Preview</button></p></div><div class="panel"><h3>RCS Message Preview</h3><div class="phone"><b>GURUKRIPA ENTERPRISES</b><p class="muted">Business message · Sample</p><div class="bubble" id="messagePreview">Explore stationery and business books from Gurukripa Enterprises.</div><p id="ctaPreview">Enquire on WhatsApp</p></div></div></div></div></section><script src="/rcs.js"></script>'''
index=page('Home','<section class="hero"><div class="wrap"><h1>Gurukripa Enterprises</h1><p>Registers, notebooks, account books, receipt books, order books, letter pads and diaries in Satpur, Maharashtra.</p><a class="btn" href="/contact.html">Get a Quote</a></div></section>'+section('<h2>Our Product Collection</h2>'+cards)+rcs)
(p/'index.html').write_text(index)
(p/'products.html').write_text(page('Products',section('<h1>Our Products</h1>'+cards)))
(p/'about.html').write_text(page('About Us',section('<h1>About Gurukripa Enterprises</h1><p>We offer registers, account books, notebooks, order books, receipt books, letter pads, memorandum pads and diaries for office and business use.</p>')))
(p/'contact.html').write_text(page('Contact Us',section('<h1>Contact Gurukripa Enterprises</h1><p>R 1671, Matruchhaya Row House, Rajya Karmchari Vasahat, Satpur, Maharashtra 422012</p><p>Phone: <a href="tel:+918698004560">+91 86980 04560</a></p><a class="btn" href="https://wa.me/918698004560">WhatsApp Enquiry</a>')))
(p/'privacy-policy.html').write_text(page('Privacy Policy',section('<h1>Privacy Policy</h1><p>Enquiries sent through WhatsApp are handled through WhatsApp. This static website does not maintain an enquiry database.</p><p>Contact +91 86980 04560 for privacy-related questions.</p>')))
(p/'terms-and-conditions.html').write_text(page('Terms & Conditions',section('<h1>Terms & Conditions</h1><p>Product details, prices and availability are subject to direct confirmation. RCS SMS dashboard is a non-operational demo.</p>')))
